    // readProbeSample decodes value from the first numBits of data — the family read
    // verdict: false rejects the wire (bounds, ranges, wire constants, padding);
    // hostile bytes never throw. No slack past the payload is required.
    public static boolean readProbeSample(ProbeSample value, byte[] data, int numBits) {
        if (numBits > (long) data.length * 8) {
            return false; // the payload cannot exceed the buffer behind data
        }
        // the final 64-bit window, assembled once so every load stays inside
        // the buffer (the family's no-slack reader stance)
        int tailBase = data.length - 8;
        long tailWord = 0;
        if (tailBase >= 0) {
            tailWord = (long) LONG_LE.get(data, tailBase);
        } else {
            tailBase = 0;
            for (int i = data.length - 1; i >= 0; i--) {
                tailWord = (tailWord << 8) | (data[i] & 0xffL);
            }
        }
        int bitsRead = 0;
        long window = 0;
        int shift = 0;
        long v = 0;
        long lo = 0;
        if (bitsRead + 113 > numBits) {
            return false;
        }
        if (bitsRead >>> 3 < tailBase) {
            window = (long) LONG_LE.get(data, bitsRead >>> 3);
            shift = bitsRead & 7;
        } else {
            window = tailWord;
            shift = bitsRead - tailBase * 8;
        }
        v = (window >>> shift) & 0x1L;
        bitsRead += 1;
        value.active = v != 0;
        if (bitsRead >>> 3 < tailBase) {
            window = (long) LONG_LE.get(data, bitsRead >>> 3);
            shift = bitsRead & 7;
        } else {
            window = tailWord;
            shift = bitsRead - tailBase * 8;
        }
        v = (window >>> shift) & 0xffffL;
        bitsRead += 16;
        if (v > 36000L) {
            return false; // headroom above the quantum count is refused
        }
        value.orientation = (float) v / 36000.0f * 360.0f + -180.0f;
        if (bitsRead >>> 3 < tailBase) {
            window = (long) LONG_LE.get(data, bitsRead >>> 3);
            shift = bitsRead & 7;
        } else {
            window = tailWord;
            shift = bitsRead - tailBase * 8;
        }
        v = (window >>> shift) & 0xffffffffL;
        bitsRead += 32;
        value.rawDelta = (int) v;
        if (bitsRead >>> 3 < tailBase) {
            window = (long) LONG_LE.get(data, bitsRead >>> 3);
            shift = bitsRead & 7;
        } else {
            window = tailWord;
            shift = bitsRead - tailBase * 8;
        }
        v = (window >>> shift) & 0xffffffffL;
        bitsRead += 32;
        lo = v;
        if (bitsRead >>> 3 < tailBase) {
            window = (long) LONG_LE.get(data, bitsRead >>> 3);
            shift = bitsRead & 7;
        } else {
            window = tailWord;
            shift = bitsRead - tailBase * 8;
        }
        v = (window >>> shift) & 0xffffffffL;
        bitsRead += 32;
        lo |= v << 32;
        value.bigDelta = lo;
        if (value.active) {
            if (bitsRead + 5 > numBits) {
                return false;
            }
            if (bitsRead >>> 3 < tailBase) {
                window = (long) LONG_LE.get(data, bitsRead >>> 3);
                shift = bitsRead & 7;
            } else {
                window = tailWord;
                shift = bitsRead - tailBase * 8;
            }
            v = (window >>> shift) & 0xfL;
            bitsRead += 4;
            value.weapon = (byte) v;
            if (bitsRead >>> 3 < tailBase) {
                window = (long) LONG_LE.get(data, bitsRead >>> 3);
                shift = bitsRead & 7;
            } else {
                window = tailWord;
                shift = bitsRead - tailBase * 8;
            }
            v = (window >>> shift) & 0x1L;
            bitsRead += 1;
            value.hasTarget = v != 0;
            if (value.hasTarget) {
                if (bitsRead + 16 > numBits) {
                    return false;
                }
                if (bitsRead >>> 3 < tailBase) {
                    window = (long) LONG_LE.get(data, bitsRead >>> 3);
                    shift = bitsRead & 7;
                } else {
                    window = tailWord;
                    shift = bitsRead - tailBase * 8;
                }
                v = (window >>> shift) & 0xffffL;
                bitsRead += 16;
                value.targetId = (short) v;
            } else {
                value.targetId = 0;
            }
            value.idleTicks = 0;
        } else {
            if (bitsRead + 32 > numBits) {
                return false;
            }
            if (bitsRead >>> 3 < tailBase) {
                window = (long) LONG_LE.get(data, bitsRead >>> 3);
                shift = bitsRead & 7;
            } else {
                window = tailWord;
                shift = bitsRead - tailBase * 8;
            }
            v = (window >>> shift) & 0xffffffffL;
            bitsRead += 32;
            value.idleTicks = (int) v;
            value.weapon = 0;
            value.hasTarget = false;
            value.targetId = 0;
        }
        if (bitsRead + 3 > numBits) {
            return false;
        }
        if (bitsRead >>> 3 < tailBase) {
            window = (long) LONG_LE.get(data, bitsRead >>> 3);
            shift = bitsRead & 7;
        } else {
            window = tailWord;
            shift = bitsRead - tailBase * 8;
        }
        v = (window >>> shift) & 0x7L;
        bitsRead += 3;
        value.samplesCount = (int) (v + 1);
        if (bitsRead + value.samplesCount * 16L > numBits) {
            return false;
        }
        for (int i0 = 0; i0 < value.samplesCount; i0++) {
            if (bitsRead >>> 3 < tailBase) {
                window = (long) LONG_LE.get(data, bitsRead >>> 3);
                shift = bitsRead & 7;
            } else {
                window = tailWord;
                shift = bitsRead - tailBase * 8;
            }
            v = (window >>> shift) & 0xffffL;
            bitsRead += 16;
            value.samples[i0] = (short) v;
        }
        return true;
    }

    // measureProbeSample is the exact wire bits writeProbeSample would produce for value —
    // trusted like the writer; static runs fold to literals at generation time.
    public static int measureProbeSample(ProbeSample value) {
        int bits = 0;
        bits += 113;
        if (value.active) {
            bits += 5;
            if (value.hasTarget) {
                bits += 16;
            }
        } else {
            bits += 32;
        }
        bits += 3;
        bits += value.samplesCount * 16;
        return bits;
    }

