    // measureProbeCollider is the exact wire bits writeProbeCollider would produce for value —
    // trusted like the writer; static runs fold to literals at generation time.
    public static int measureProbeCollider(ProbeCollider value) {
        int bits = 0;
        bits += 8;
        bits += 2;
        switch (value.shape.type) {
            case 1:
                bits += 16;
                break;
            case 2:
                bits += 15;
                break;
        }
        bits += 2;
        switch (value.backup.type) {
            case 1:
                bits += 16;
                break;
            case 2:
                bits += 15;
                break;
        }
        bits += 2;
        for (int i0 = 0; i0 < value.extrasCount; i0++) {
            final ProbeShape e0 = value.extras[i0];
            bits += 2;
            switch (e0.type) {
                case 1:
                    bits += 16;
                    break;
                case 2:
                    bits += 15;
                    break;
            }
        }
        return bits;
    }

