    // writeProbeReport packs value into data — the trusted writer (contracts in the
    // checkWriteProbeReport predicate, one dormant assert call without -ea). The buffer
    // must hold probeReportMaxBytes. Returns the bytes written.
    public static int writeProbeReport(ProbeReport value, byte[] data) {
        assert checkWriteProbeReport(value, data);
        long scratch = 0;
        int scratchBits = 0;
        int wordIndex = 0;
        long v = 0;
        v = 171;
        scratch |= v << scratchBits;
        scratchBits += 8;
        if (scratchBits >= 64) {
            LONG_LE.set(data, wordIndex * 8, scratch);
            wordIndex++;
            scratchBits -= 64;
            scratch = v >>> (8 - scratchBits);
        }
        v = value.header.version & 0x7L;
        scratch |= v << scratchBits;
        scratchBits += 3;
        if (scratchBits >= 64) {
            LONG_LE.set(data, wordIndex * 8, scratch);
            wordIndex++;
            scratchBits -= 64;
            scratch = v >>> (3 - scratchBits);
        }
        v = 0;
        scratch |= v << scratchBits;
        scratchBits += 5;
        if (scratchBits >= 64) {
            LONG_LE.set(data, wordIndex * 8, scratch);
            wordIndex++;
            scratchBits -= 64;
            scratch = v >>> (5 - scratchBits);
        }
        {
            final int pad = scratchBits & 7;
            if (pad != 0) {
                scratchBits += 8 - pad;
                if (scratchBits >= 64) {
                    LONG_LE.set(data, wordIndex * 8, scratch);
                    wordIndex++;
                    scratchBits -= 64;
                    scratch = 0;
                }
            }
        }
        v = value.header.probeId & 0xffffffffL;
        scratch |= v << scratchBits;
        scratchBits += 32;
        if (scratchBits >= 64) {
            LONG_LE.set(data, wordIndex * 8, scratch);
            wordIndex++;
            scratchBits -= 64;
            scratch = v >>> (32 - scratchBits);
        }
        v = (value.header.probeId >>> 32) & 0xffffffffL;
        scratch |= v << scratchBits;
        scratchBits += 32;
        if (scratchBits >= 64) {
            LONG_LE.set(data, wordIndex * 8, scratch);
            wordIndex++;
            scratchBits -= 64;
            scratch = v >>> (32 - scratchBits);
        }
        v = value.flags & 0xffL;
        scratch |= v << scratchBits;
        scratchBits += 8;
        if (scratchBits >= 64) {
            LONG_LE.set(data, wordIndex * 8, scratch);
            wordIndex++;
            scratchBits -= 64;
            scratch = v >>> (8 - scratchBits);
        }
        v = value.echo.testA & 0xffffL;
        scratch |= v << scratchBits;
        scratchBits += 16;
        if (scratchBits >= 64) {
            LONG_LE.set(data, wordIndex * 8, scratch);
            wordIndex++;
            scratchBits -= 64;
            scratch = v >>> (16 - scratchBits);
        }
        v = (value.echo.testB) & 0x3ffL;
        scratch |= v << scratchBits;
        scratchBits += 10;
        if (scratchBits >= 64) {
            LONG_LE.set(data, wordIndex * 8, scratch);
            wordIndex++;
            scratchBits -= 64;
            scratch = v >>> (10 - scratchBits);
        }
        v = (value.echo.testC) & 0x3ffL;
        scratch |= v << scratchBits;
        scratchBits += 10;
        if (scratchBits >= 64) {
            LONG_LE.set(data, wordIndex * 8, scratch);
            wordIndex++;
            scratchBits -= 64;
            scratch = v >>> (10 - scratchBits);
        }
        v = (value.echo.testD) & 0x3ffL;
        scratch |= v << scratchBits;
        scratchBits += 10;
        if (scratchBits >= 64) {
            LONG_LE.set(data, wordIndex * 8, scratch);
            wordIndex++;
            scratchBits -= 64;
            scratch = v >>> (10 - scratchBits);
        }
        if (scratchBits != 0) {
            LONG_LE.set(data, wordIndex * 8, scratch);
        }
        return wordIndex * 8 + ((scratchBits + 7) >>> 3);
    }

    // readProbeReport decodes value from the first numBits of data — the family read
    // verdict: false rejects the wire (bounds, ranges, wire constants, padding);
    // hostile bytes never throw. No slack past the payload is required.
    public static boolean readProbeReport(ProbeReport value, byte[] data, int numBits) {
        if (numBits > (long) data.length * 8) {
            return false; // the payload cannot exceed the buffer behind data
        }
        // the final 64-bit window, assembled once so every load stays inside
        // the buffer (the family's no-slack reader stance)
        int tailBase = data.length - 8;
        long tailWord = 0;
        if (tailBase >= 0) {
            tailWord = (long) LONG_LE.get(data, tailBase);
        } else {
            tailBase = 0;
            for (int i = data.length - 1; i >= 0; i--) {
                tailWord = (tailWord << 8) | (data[i] & 0xffL);
            }
        }
        int bitsRead = 0;
        long window = 0;
        int shift = 0;
        long v = 0;
        long lo = 0;
        if (bitsRead + 16 > numBits) {
            return false;
        }
        if (bitsRead >>> 3 < tailBase) {
            window = (long) LONG_LE.get(data, bitsRead >>> 3);
            shift = bitsRead & 7;
        } else {
            window = tailWord;
            shift = bitsRead - tailBase * 8;
        }
        v = (window >>> shift) & 0xffL;
        bitsRead += 8;
        if (v != 171) {
            return false; // a read rejects any other value (SPEC §4.3)
        }
        if (bitsRead >>> 3 < tailBase) {
            window = (long) LONG_LE.get(data, bitsRead >>> 3);
            shift = bitsRead & 7;
        } else {
            window = tailWord;
            shift = bitsRead - tailBase * 8;
        }
        v = (window >>> shift) & 0x7L;
        bitsRead += 3;
        value.header.version = (int) v;
        if (bitsRead >>> 3 < tailBase) {
            window = (long) LONG_LE.get(data, bitsRead >>> 3);
            shift = bitsRead & 7;
        } else {
            window = tailWord;
            shift = bitsRead - tailBase * 8;
        }
        v = (window >>> shift) & 0x1fL;
        bitsRead += 5;
        if (v != 0) {
            return false; // reserved bits must read zero (SPEC §4.3)
        }
        {
            final int pad = bitsRead & 7;
            if (pad != 0) {
                if (bitsRead + (8 - pad) > numBits) {
                    return false;
                }
                if ((data[bitsRead >>> 3] & 0xff) >>> pad != 0) {
                    return false; // nonzero padding is refused (SPEC §4.3)
                }
                bitsRead += 8 - pad;
            }
        }
        if (bitsRead + 64 > numBits) {
            return false;
        }
        if (bitsRead >>> 3 < tailBase) {
            window = (long) LONG_LE.get(data, bitsRead >>> 3);
            shift = bitsRead & 7;
        } else {
            window = tailWord;
            shift = bitsRead - tailBase * 8;
        }
        v = (window >>> shift) & 0xffffffffL;
        bitsRead += 32;
        lo = v;
        if (bitsRead >>> 3 < tailBase) {
            window = (long) LONG_LE.get(data, bitsRead >>> 3);
            shift = bitsRead & 7;
        } else {
            window = tailWord;
            shift = bitsRead - tailBase * 8;
        }
        v = (window >>> shift) & 0xffffffffL;
        bitsRead += 32;
        lo |= v << 32;
        value.header.probeId = lo;
        if (bitsRead + 54 > numBits) {
            return false;
        }
        if (bitsRead >>> 3 < tailBase) {
            window = (long) LONG_LE.get(data, bitsRead >>> 3);
            shift = bitsRead & 7;
        } else {
            window = tailWord;
            shift = bitsRead - tailBase * 8;
        }
        v = (window >>> shift) & 0xffL;
        bitsRead += 8;
        value.flags = v;
        if (bitsRead >>> 3 < tailBase) {
            window = (long) LONG_LE.get(data, bitsRead >>> 3);
            shift = bitsRead & 7;
        } else {
            window = tailWord;
            shift = bitsRead - tailBase * 8;
        }
        v = (window >>> shift) & 0xffffL;
        bitsRead += 16;
        value.echo.testA = (short) v;
        if (bitsRead >>> 3 < tailBase) {
            window = (long) LONG_LE.get(data, bitsRead >>> 3);
            shift = bitsRead & 7;
        } else {
            window = tailWord;
            shift = bitsRead - tailBase * 8;
        }
        v = (window >>> shift) & 0x3ffL;
        bitsRead += 10;
        if (v > 1000) {
            return false; // a smuggled offset is refused
        }
        value.echo.testB = (short) v;
        if (bitsRead >>> 3 < tailBase) {
            window = (long) LONG_LE.get(data, bitsRead >>> 3);
            shift = bitsRead & 7;
        } else {
            window = tailWord;
            shift = bitsRead - tailBase * 8;
        }
        v = (window >>> shift) & 0x3ffL;
        bitsRead += 10;
        if (v > 1000) {
            return false; // a smuggled offset is refused
        }
        value.echo.testC = (short) v;
        if (bitsRead >>> 3 < tailBase) {
            window = (long) LONG_LE.get(data, bitsRead >>> 3);
            shift = bitsRead & 7;
        } else {
            window = tailWord;
            shift = bitsRead - tailBase * 8;
        }
        v = (window >>> shift) & 0x3ffL;
        bitsRead += 10;
        if (v > 1000) {
            return false; // a smuggled offset is refused
        }
        value.echo.testD = (short) v;
        return true;
    }

    // measureProbeReport is the exact wire bits writeProbeReport would produce for value —
