    // measureTestData is the exact wire bits writeTestData would produce for value —
    // trusted like the writer; static runs fold to literals at generation time.
    public static int measureTestData(TestData value) {
        int bits = 0;
        bits += 54;
        bits += value.itemsCount * 8;
        bits += 355;
        bits += (8 - (bits & 7)) & 7;
        bits += 144;
        bits += (8 - (bits & 7)) & 7;
        bits += value.textLength * 8;
        return bits;
    }

    // type CompressedProbe
    public static final class CompressedProbe {
        // compressed float [0.0, 10.0] @ 0.01
        public float boundary;
        // compressed float [-5.0, 5.0] @ 0.001
        public float offset;
    }

    // compressedProbeMaxBits is the longest wire path; align pads at worst case (SPEC §6.1).
    // compressedProbeMaxBytes is rounded up to the 8-byte write-buffer granularity.
    public static final int compressedProbeMaxBits = 24;
    public static final int compressedProbeMaxBytes = 8;

    // The §5 zero form: all-zero storage; specified defaults live only in
    // construction.
    public static void zeroCompressedProbe(CompressedProbe value) {
        value.boundary = 0.0f;
        value.offset = 0.0f;
    }

    // Restore construction defaults in place; buffers and objects are retained.
    public static void initCompressedProbe(CompressedProbe value) {
        value.boundary = 0.0f;
        value.offset = 0.0f;
    }

    // checkWriteCompressedProbe is writeCompressedProbe's contract walk, called once through assert —
    // the predicate-extraction form: dormant assert bodies count against the
    // JIT's inline thresholds, so the hot body carries one small call and the
    // contracts live here (issue #156).
    private static boolean checkWriteCompressedProbe(CompressedProbe value, byte[] data) {
        assert data.length % 8 == 0;
        assert data.length >= compressedProbeMaxBytes;
        assert value.boundary - value.boundary == 0.0f; // finite: NaN and both infinities fail this
        assert value.offset - value.offset == 0.0f; // finite: NaN and both infinities fail this
        return true;
    }

    // writeCompressedProbe packs value into data — the trusted writer (contracts in the
    // checkWriteCompressedProbe predicate, one dormant assert call without -ea). The buffer
    // must hold compressedProbeMaxBytes. Returns the bytes written.
    public static int writeCompressedProbe(CompressedProbe value, byte[] data) {
        assert checkWriteCompressedProbe(value, data);
        long scratch = 0;
        int scratchBits = 0;
        int wordIndex = 0;
        long v = 0;
        {
            float n = (value.boundary - 0.0f) / 10.0f;
            if (!(n >= 0.0f)) {
                n = 0.0f;
            } else if (!(n <= 1.0f)) {
                n = 1.0f;
            }
            // two roundings, not one: the product rounds to float32 BEFORE 0.5
            // is added, and the sum rounds before the floor (SPEC §4.3)
            v = (long) Math.floor(n * 1000.0f + 0.5f);
        }
        scratch |= v << scratchBits;
        scratchBits += 10;
        if (scratchBits >= 64) {
            LONG_LE.set(data, wordIndex * 8, scratch);
            wordIndex++;
            scratchBits -= 64;
            scratch = v >>> (10 - scratchBits);
        }
        {
            float n = (value.offset - -5.0f) / 10.0f;
            if (!(n >= 0.0f)) {
                n = 0.0f;
            } else if (!(n <= 1.0f)) {
                n = 1.0f;
            }
            // two roundings, not one: the product rounds to float32 BEFORE 0.5
            // is added, and the sum rounds before the floor (SPEC §4.3)
            v = (long) Math.floor(n * 10000.0f + 0.5f);
        }
        scratch |= v << scratchBits;
        scratchBits += 14;
        if (scratchBits >= 64) {
            LONG_LE.set(data, wordIndex * 8, scratch);
            wordIndex++;
            scratchBits -= 64;
            scratch = v >>> (14 - scratchBits);
        }
        if (scratchBits != 0) {
            LONG_LE.set(data, wordIndex * 8, scratch);
        }
        return wordIndex * 8 + ((scratchBits + 7) >>> 3);
    }

    // readCompressedProbe decodes value from the first numBits of data — the family read
    // verdict: false rejects the wire (bounds, ranges, wire constants, padding);
    // hostile bytes never throw. No slack past the payload is required.
    public static boolean readCompressedProbe(CompressedProbe value, byte[] data, int numBits) {
        if (numBits > (long) data.length * 8) {
            return false; // the payload cannot exceed the buffer behind data
        }
        // the final 64-bit window, assembled once so every load stays inside
        // the buffer (the family's no-slack reader stance)
        int tailBase = data.length - 8;
        long tailWord = 0;
        if (tailBase >= 0) {
            tailWord = (long) LONG_LE.get(data, tailBase);
        } else {
            tailBase = 0;
            for (int i = data.length - 1; i >= 0; i--) {
                tailWord = (tailWord << 8) | (data[i] & 0xffL);
            }
        }
        int bitsRead = 0;
        long window = 0;
        int shift = 0;
        long v = 0;
        if (bitsRead + 24 > numBits) {
            return false;
        }
        if (bitsRead >>> 3 < tailBase) {
            window = (long) LONG_LE.get(data, bitsRead >>> 3);
            shift = bitsRead & 7;
        } else {
            window = tailWord;
            shift = bitsRead - tailBase * 8;
        }
        v = (window >>> shift) & 0x3ffL;
        bitsRead += 10;
        if (v > 1000L) {
            return false; // headroom above the quantum count is refused
        }
        value.boundary = (float) v / 1000.0f * 10.0f + 0.0f;
        if (bitsRead >>> 3 < tailBase) {
            window = (long) LONG_LE.get(data, bitsRead >>> 3);
            shift = bitsRead & 7;
        } else {
            window = tailWord;
            shift = bitsRead - tailBase * 8;
        }
        v = (window >>> shift) & 0x3fffL;
        bitsRead += 14;
        if (v > 10000L) {
            return false; // headroom above the quantum count is refused
        }
        value.offset = (float) v / 10000.0f * 10.0f + -5.0f;
        return true;
    }

    // measureCompressedProbe is the exact wire bits writeCompressedProbe would produce for value —
    // trusted like the writer; static runs fold to literals at generation time.
